# Load all grids seen so far
def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    # Try to find session log
    try:
        t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    except:
        try:
            t = open('/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-3/play/users/u051/system/state/sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
        except:
            t = ""

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rest = t[m.end():].split('\n')[:h]
        if w > 0 and k not in G and all(len(r) == w for r in rest):
            try:
                grid = [[int(x) for x in r.split()] for r in rest if r.strip()]
                G[k] = grid
            except:
                pass
    return G

G = load_grids()
for k in sorted(G.keys()):
    print(f"{k}: {G[k]}")
